package br.com.inframonitor.relatorio.temporal;
import br.com.inframonitor.equipamento.entity.Equipamento; import br.com.inframonitor.monitor.entity.*; import br.com.inframonitor.monitor.repository.MonitorRepository; import br.com.inframonitor.medicao.repository.MedicaoRepository; import br.com.inframonitor.incidente.repository.IncidenteRepository; import br.com.inframonitor.relatorio.repository.JanelaMonitoramentoRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*; import java.util.stream.*;
@Service @Transactional(readOnly=true) public class DisponibilidadeEquipamentoTemporalService {
 private final MonitorRepository monitors; private final JanelaMonitoramentoRepository janelas; private final MedicaoRepository medicoes; private final IncidenteRepository incidentes;
 public DisponibilidadeEquipamentoTemporalService(MonitorRepository a,JanelaMonitoramentoRepository b,MedicaoRepository c,IncidenteRepository d){monitors=a;janelas=b;medicoes=c;incidentes=d;}
 public List<DisponibilidadeEquipamentoTemporalResponse> calcular(Equipamento e,Instant inicio,Instant fim){ return calcularTodos(List.of(e), inicio, fim); }
 public List<DisponibilidadeEquipamentoTemporalResponse> calcularTodos(Collection<Equipamento> es, Instant inicio, Instant fim){
  if(es.isEmpty()) return List.of(); var equipamentoPorId=es.stream().collect(Collectors.toMap(Equipamento::getId, x->x));
  var ms=monitors.findByEquipamentoIdIn(new ArrayList<>(equipamentoPorId.keySet())).stream().filter(m->m.getTipo()==TipoMonitor.ICMP).toList();
  var ids=ms.stream().map(Monitor::getId).toList(); var js=ids.isEmpty()?List.<br.com.inframonitor.relatorio.entity.JanelaMonitoramento>of():janelas.noPeriodo(ids,inicio,fim); var md=ids.isEmpty()?List.<br.com.inframonitor.medicao.entity.Medicao>of():medicoes.noPeriodo(ids,inicio,fim); var inc=ids.isEmpty()?List.<br.com.inframonitor.incidente.entity.Incidente>of():incidentes.noPeriodo(ids,inicio,fim);
  var porEquipamento=ms.stream().collect(Collectors.groupingBy(m->m.getEquipamento().getId())); var resposta=new ArrayList<DisponibilidadeEquipamentoTemporalResponse>();
  for(var e:es){var monitores=porEquipamento.getOrDefault(e.getId(),List.of()); if(monitores.isEmpty()){resposta.add(new DisponibilidadeEquipamentoTemporalResponse(e.getId(),e.getNome(),null,null,EstadoAnalitico.SEM_MONITORAMENTO,null,null,null,null,null,0));continue;} for(var m:monitores){var x=DisponibilidadeTemporalCalculator.calcular(inicio,fim,js.stream().filter(j->j.getMonitor().getId().equals(m.getId())).map(j->new DisponibilidadeTemporalCalculator.Janela(j.getInicioEm(),j.getFimEm(),md.stream().filter(q->q.getMonitor().getId().equals(m.getId())&&!q.getExecutadoEm().isBefore(j.getInicioEm())&&(j.getFimEm()==null||q.getExecutadoEm().isBefore(j.getFimEm()))).map(q->q.getExecutadoEm()).min(Comparator.naturalOrder()).orElse(null),j.getOrigem())).toList(),inc.stream().filter(i->i.getMonitor().getId().equals(m.getId())).map(i->new DisponibilidadeTemporalCalculator.Incidente(i.getId(),i.getIniciadoEm(),i.getEncerradoEm())).toList());resposta.add(new DisponibilidadeEquipamentoTemporalResponse(e.getId(),e.getNome(),m.getId(),m.getNome(),x.estadoAnalitico(),x.qualidadeJanela(),x.tempoMonitoradoSegundos(),x.tempoIndisponivelSegundos(),x.tempoDisponivelSegundos(),x.disponibilidadePercentual(),x.incidentes()));}}
  return List.copyOf(resposta); }
}
